// Deterministic checks done here, without paid APIs: sitemap URLs, homepage schema types, llms.txt, robots.txt.
const c = $('Config').first().json;
const get = async (url) => {
  try {
    const r = await this.helpers.httpRequest({ url, method: 'GET', returnFullResponse: true, ignoreHttpStatusErrors: true, timeout: 20000, headers: { 'User-Agent': 'LivoSEOBot/1.0' } });
    return { status: r.statusCode, body: typeof r.body === 'string' ? r.body : JSON.stringify(r.body) };
  } catch (e) { return { status: 0, body: '', error: e.message }; }
};
const locs = (xml) => [...xml.matchAll(/<loc>\s*([^<\s]+)\s*<\/loc>/g)].map(m => m[1]);

// Sitemap (handles a sitemap index one level deep)
const sm = await get(c.base + '/sitemap.xml');
let pages = [], sitemaps = [];
if (sm.status === 200) {
  if (/<sitemapindex/i.test(sm.body)) {
    sitemaps = locs(sm.body);
    for (const s of sitemaps.slice(0, 10)) { const r = await get(s); if (r.status === 200) pages.push(...locs(r.body)); }
  } else pages = locs(sm.body);
}
pages = [...new Set(pages)].filter(u => !/\.(jpg|jpeg|png|webp|gif|svg|pdf)$/i.test(u));
const home = c.base + '/';
const urls = [home, ...pages.filter(u => u.replace(/\/$/, '') !== c.base)].slice(0, c.maxPages);

// Homepage structured data (JSON-LD @type values)
const hp = await get(home);
const types = new Set();
for (const m of hp.body.matchAll(/<script[^>]*application\/ld\+json[^>]*>([\s\S]*?)<\/script>/gi)) {
  for (const t of m[1].matchAll(/"@type"\s*:\s*(\[[^\]]*\]|"[^"]+")/g)) {
    t[1].replace(/[\[\]"]/g, '').split(',').map(s => s.trim()).filter(Boolean).forEach(x => types.add(x));
  }
}
const llms = await get(c.base + '/llms.txt');
const robots = await get(c.base + '/robots.txt');

return [{ json: {
  urls,
  checks: {
    sitemap: { status: sm.status, isIndex: sitemaps.length > 0, childSitemaps: sitemaps.length, pagesListed: pages.length },
    homepage: { status: hp.status, jsonLdTypes: [...types], hasFaqText: /faq|frequently asked|got questions/i.test(hp.body) },
    llmsTxt: { status: llms.status, firstLine: llms.status === 200 ? llms.body.split('\n')[0].slice(0, 120) : null },
    robotsTxt: { status: robots.status, mentionsSitemap: /sitemap:/i.test(robots.body), disallowAll: /^disallow:\s*\/\s*$/im.test(robots.body) }
  }
} }];

// Compact summary for the agent: facts only, small enough for a cheap model.
const c = $('Config').first().json;
const d = $('Discover').first().json;
const errOf = (x) => (x && x.error) ? String(x.error.message || x.error.description || JSON.stringify(x.error)).slice(0, 300) : null;
const sc = (x) => (x && x.structuredContent) || {};

// On-page: OpenSEO site audit (runs monthly; the latest completed audit is read every time)
const gate = $('Audit gate').first().json;
const ai = $('OpenSEO audit issues').first().json || {};
const iss = sc(ai);
let started = null;
try { started = sc($('OpenSEO audit start').first().json); } catch (e) { started = null; }
const issues = (iss.issues || []).map(i => ({ severity: i.severity, issueType: i.issueType, url: i.url, details: i.details, howToFix: String(i.howToFix || '').slice(0, 220) }));
const onpage = {
  audit: { auditId: gate.auditId, completedAt: gate.completedAt, pagesCrawled: gate.pagesCrawled, sitemapPagesListed: (d.checks.sitemap || {}).pagesListed,
           startedThisRun: !!(started && !errOf($('OpenSEO audit start').first().json)), plan: gate.reason },
  issueSummary: iss.summary || [],
  issues,
  error: gate.auditId ? errOf(ai) : null,
  note: gate.auditId ? null : 'No completed OpenSEO audit exists yet (' + gate.reason + '). Say so; do not report on-page findings.'
};

// PageSpeed (mobile, homepage)
const ps = $('PageSpeed').first().json || {};
const lh = ps.lighthouseResult || {};
const cat = lh.categories || {}, au = lh.audits || {};
const pagespeed = lh.categories ? {
  performance: Math.round((cat.performance || {}).score * 100),
  lcp: (au['largest-contentful-paint'] || {}).displayValue,
  cls: (au['cumulative-layout-shift'] || {}).displayValue,
  tbt: (au['total-blocking-time'] || {}).displayValue
} : { error: errOf(ps) || 'PageSpeed unavailable' };

// Google Maps / local pack positions from OpenSEO local SERP, one item per keyword
const kws = $('Local keywords').all().map(i => i.json.keyword);
const mine = (s) => { s = String(s || '').toLowerCase(); return s.includes(c.site) || c.brand.some(b => s.includes(b)); };
const maps = $('OpenSEO local SERP').all().map((i, n) => {
  const rows = sc(i.json).results || [];
  const hit = rows.find(x => mine(x.domain) || mine(x.title));
  return { keyword: kws[n], position: hit ? hit.rank_absolute : null, matched: hit ? hit.title : null,
           top3: rows.slice(0, 3).map(x => x.title + (x.rating ? ' (' + x.rating.value + '★/' + x.rating.votes_count + ')' : '')),
           error: errOf(i.json) || (rows.length ? null : 'no rows returned') };
});

// OpenSEO rank tracker (Google organic, mobile) and AI answer visibility
const rk = sc($('OpenSEO rankings').first().json);
const cfg = rk.config || null;
const rankings = cfg ? {
  tracker: { domain: cfg.domain, location: cfg.locationName, device: cfg.devices, depth: cfg.serpDepth, schedule: cfg.scheduleInterval, lastCheckedAt: cfg.lastCheckedAt },
  note: 'position null = not found in the top ' + cfg.serpDepth + ' results the check returned, not proof of a lower rank',
  totalKeywords: (rk.results || {}).totalCount,
  keywords: ((rk.results || {}).rows || []).map(r => ({ keyword: r.keyword, position: (r.mobile || {}).position, previousPosition: (r.mobile || {}).previousPosition,
    rankingUrl: (r.mobile || {}).rankingUrl, serpFeatures: (r.mobile || {}).serpFeatures || [] }))
} : { error: errOf($('OpenSEO rankings').first().json) || 'No rank tracker found for this OpenSEO project' };
const aiD = sc($('OpenSEO AI').first().json).data;
const aiVisibility = aiD ? {
  runId: aiD.runId, run: aiD.run, coverage: aiD.coverage, totalRows: aiD.totalCount,
  summaries: (aiD.summaries || []).slice(0, 20), rows: (aiD.rows || []).slice(0, 40),
  note: aiD.runId ? null : 'No AI visibility check has been run yet for this site, so there is no data. Do not infer anything.'
} : { error: errOf($('OpenSEO AI').first().json) || 'AI visibility results unavailable' };


// Backlinks (OpenSEO, refreshed monthly; otherwise the copy saved in the last snapshot)
const bg = $('Backlinks gate').first().json;
let backlinks;
if (bg.refresh) {
  try {
    const ovN = $('OpenSEO backlinks overview').first().json, rwN = $('OpenSEO backlinks rows').first().json;
    const ov = (((sc(ovN).overview || {}).overview) || {}), sm = ov.summary || {};
    const rows = ((sc(rwN).backlinks || {}).rows || []).map(r => ({ domainFrom: r.domainFrom, urlFrom: r.urlFrom, urlTo: r.urlTo, anchor: String(r.anchor || '').slice(0, 90),
      dofollow: r.isDofollow, spamScore: r.spamScore, firstSeen: r.firstSeen, lost: r.isLost })).slice(0, 100);
    if (!rows.length && !sm.backlinks) throw new Error(errOf(ovN) || errOf(rwN) || 'no backlink data returned');
    const prev = (bg.cached || {}).rows || null;
    const key = (r) => r.urlFrom + '>' + r.urlTo;
    const prevKeys = new Set((prev || []).map(key));
    const since = (bg.cached || {}).fetchedAt ? new Date(bg.cached.fetchedAt).getTime() : Date.now() - 35 * 86400000;
    const isNew = (r) => prev ? !prevKeys.has(key(r)) : new Date(String(r.firstSeen).replace(' +00:00', 'Z').replace(' ', 'T')).getTime() > since;
    backlinks = { fetchedAt: new Date().toISOString(), live: true, comparedWith: (bg.cached || {}).fetchedAt || null,
      overview: { backlinks: sm.backlinks, referringDomains: sm.referringDomains, brokenBacklinks: sm.brokenBacklinks, backlinksSpamScore: sm.backlinksSpamScore, trends: ov.trends, newLostTrends: ov.newLostTrends },
      totalRows: ((sc(rwN).backlinks || {}).totalCount), rows };
  } catch (e) { backlinks = { error: String(e.message || e).slice(0, 200), live: true }; }
} else backlinks = Object.assign({}, bg.cached, { live: false, note: bg.reason });
if (backlinks.rows) {
  const SPAM = 40;
  const prevRows = (bg.cached && bg.refresh) ? (bg.cached.rows || null) : null;
  const pk = new Set((prevRows || []).map(r => r.urlFrom + '>' + r.urlTo));
  const cutoff = Date.now() - 35 * 86400000;
  const fresh = backlinks.rows.filter(r => prevRows ? !pk.has(r.urlFrom + '>' + r.urlTo) : (new Date(String(r.firstSeen).replace(' +00:00', 'Z').replace(' ', 'T')).getTime() > cutoff));
  backlinks.newLinks = fresh.slice(0, 30);
  backlinks.lostLinks = backlinks.rows.filter(r => r.lost).slice(0, 30);
  const sp = backlinks.rows.filter(r => (r.spamScore || 0) >= SPAM);
  backlinks.spam = { threshold: SPAM, count: sp.length, ofRows: backlinks.rows.length, domains: [...new Set(sp.map(r => r.domainFrom))].slice(0, 15) };
}

return [{ json: {
  site: c.site, collectedAt: new Date().toISOString(),
  siteChecks: d.checks, pagesAudited: gate.pagesCrawled || 0, onpage, pagespeed,
  rankings: { location: c.location, maps },
  competitors: c.competitors || [],
  openseo: { rankings, aiVisibility, backlinks }
} }];

// Decide whether to start an OpenSEO site audit: first Monday of the month (Asia/Kolkata), or no completed audit yet.
// Never start a second one while one is running or started in the last 24 h.
const r = $json || {};
const audits = (r.structuredContent || {}).audits || [];
const now = Date.now();
const ist = new Date(now + 5.5 * 3600 * 1000);
const firstMonday = ist.getUTCDay() === 1 && ist.getUTCDate() <= 7;
const latest = audits[0];
const done = audits.find(a => a.status === 'completed');
const age = latest ? now - new Date(latest.startedAt).getTime() : Infinity;
const inFlight = !!latest && !['completed', 'failed', 'cancelled'].includes(latest.status) && age < 3 * 3600 * 1000;
let start = false, reason;
if (r.error) reason = 'audit list unavailable';
else if (inFlight) reason = 'an audit is already running';
else if (age < 24 * 3600 * 1000) reason = 'an audit started in the last 24 hours';
else if (!done) { start = true; reason = 'no completed audit yet (baseline)'; }
else if (firstMonday) { start = true; reason = 'first Monday of the month'; }
else reason = 'not the first Monday; reading the latest completed audit';
return [{ json: { start, reason, auditId: done ? done.id : null, completedAt: done ? done.completedAt : null, pagesCrawled: done ? done.pagesCrawled : null } }];

// Backlinks cost ~80 credits per site, so refresh them on the first Monday of the month (Asia/Kolkata)
// or when no earlier snapshot has them. Otherwise reuse the copy saved in seo_snapshots.
const cached = ($json || {}).backlinks || null;
const now = Date.now();
const ist = new Date(now + 5.5 * 3600 * 1000);
const firstMonday = ist.getUTCDay() === 1 && ist.getUTCDate() <= 7;
const age = cached && cached.fetchedAt ? now - new Date(cached.fetchedAt).getTime() : Infinity;
let refresh = false, reason;
if (!cached) { refresh = true; reason = 'no saved backlinks yet'; }
else if (age < 24 * 3600 * 1000) reason = 'refreshed in the last 24 hours';
else if (firstMonday) { refresh = true; reason = 'first Monday of the month'; }
else reason = 'not the first Monday; using the saved copy from ' + cached.fetchedAt;
return [{ json: { refresh, reason, cached } }];
